CREATE TABLE public.deal_team_members (deal_id text NOT NULL REFERENCES public.deals(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL CHECK (role::text IN ('dcm','issuer_legal','counsel','syndicate_admin')), PRIMARY KEY(deal_id,user_id,role));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.deal_team_members TO authenticated; GRANT ALL ON public.deal_team_members TO service_role;
ALTER TABLE public.deal_team_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.deal_signoffs (deal_id text NOT NULL REFERENCES public.deals(id) ON DELETE CASCADE, item_key text NOT NULL, role public.app_role NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_review','signed_off')), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(deal_id,item_key), CHECK ((role::text='dcm' AND item_key IN ('structure','size','tenor','bookrunners')) OR (role::text='issuer_legal' AND item_key IN ('issuer','law','restrictions','target')) OR (role::text='counsel' AND item_key IN ('documents','listing','stabilisation','notices'))));
GRANT SELECT,INSERT,UPDATE ON public.deal_signoffs TO authenticated; GRANT ALL ON public.deal_signoffs TO service_role;
ALTER TABLE public.deal_signoffs ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.deal_phase(_deal text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN stage='Settled' THEN 'closed' WHEN stage NOT IN ('Mandate','Announced') OR coalesce((bdt_state->>'stage')::int,1)>=2 OR coalesce(bdt_state->'f'->>'x:iptSpread','')<>'' THEN 'execution' ELSE 'setup' END FROM public.deals WHERE id=_deal $$;
CREATE FUNCTION public.is_deal_actor(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role::text IN ('dcm','issuer_legal','counsel')) AND NOT public.is_admin(_user) $$;
CREATE FUNCTION public.deal_team_access(_deal text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved(auth.uid()) AND EXISTS(SELECT 1 FROM public.deal_team_members WHERE deal_id=_deal AND user_id=auth.uid()) $$;
CREATE POLICY team_read ON public.deal_team_members FOR SELECT TO authenticated USING(public.is_admin(auth.uid()) OR public.deal_team_access(deal_id));
CREATE POLICY team_manage ON public.deal_team_members FOR ALL TO authenticated USING(public.is_admin(auth.uid()) AND public.can_access_deal(deal_id)) WITH CHECK(public.is_admin(auth.uid()) AND public.can_access_deal(deal_id) AND public.has_role(user_id,role));
CREATE POLICY signoffs_read ON public.deal_signoffs FOR SELECT TO authenticated USING(public.copilot_member(deal_id) OR public.deal_team_access(deal_id));
CREATE POLICY signoffs_insert ON public.deal_signoffs FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.deal_phase(deal_id)='setup' AND public.has_role(auth.uid(),role) AND EXISTS(SELECT 1 FROM public.deal_team_members t WHERE t.deal_id=deal_signoffs.deal_id AND t.user_id=auth.uid() AND t.role=deal_signoffs.role));
CREATE POLICY signoffs_update ON public.deal_signoffs FOR UPDATE TO authenticated USING(public.deal_phase(deal_id)='setup' AND public.has_role(auth.uid(),role) AND EXISTS(SELECT 1 FROM public.deal_team_members t WHERE t.deal_id=deal_signoffs.deal_id AND t.user_id=auth.uid() AND t.role=deal_signoffs.role)) WITH CHECK(user_id=auth.uid() AND public.deal_phase(deal_id)='setup' AND public.has_role(auth.uid(),role));
CREATE OR REPLACE FUNCTION public.can_access_deal(_deal_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin(auth.uid()) OR public.deal_team_access(_deal_id) OR (NOT public.is_deal_actor(auth.uid()) AND (EXISTS(SELECT 1 FROM public.chat_channels c WHERE c.deal_id=_deal_id AND c.participant_ids ?| public.current_app_user_ids()) OR EXISTS(SELECT 1 FROM public.messages m WHERE m.deal_ids ? _deal_id AND (m.sender_id=ANY(public.current_app_user_ids()) OR m.recipients ?| public.current_app_user_ids())))) $$;
DROP POLICY "approved read deals" ON public.deals;
CREATE POLICY "approved read deals" ON public.deals FOR SELECT TO authenticated USING(public.is_approved(auth.uid()) AND (NOT public.is_deal_actor(auth.uid()) OR public.deal_team_access(id)));
CREATE POLICY actor_update_deals ON public.deals FOR UPDATE TO authenticated USING(public.deal_team_access(id) AND public.deal_phase(id)<>'closed' AND (public.has_role(auth.uid(),'dcm') OR public.deal_phase(id)='setup')) WITH CHECK(public.deal_team_access(id));
CREATE OR REPLACE FUNCTION public.copilot_editor(_deal text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.copilot_member(_deal) AND public.deal_phase(_deal)<>'closed' AND (public.is_admin(auth.uid()) OR (public.deal_team_access(_deal) AND (public.has_role(auth.uid(),'dcm') OR public.deal_phase(_deal)='setup'))) $$;
CREATE FUNCTION public.guard_deal_actor_edits() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; allowed text[]:=ARRAY['IssuanceDataGroup/Issuance/SpecifiedCurrency','IssuanceDataGroup/Issuance/TotalAggregateAmount/Value','IssuanceDataGroup/Product/AggregateNominalAmount/Value','IssuanceDataGroup/Product/Maturity/MaturityDate','IssuanceDataGroup/Product/InterestPayment/InterestType']; a jsonb; b jsonb; BEGIN
 IF auth.uid() IS NULL THEN RETURN NEW; END IF;
 IF OLD.stage='Settled' THEN RAISE EXCEPTION 'Closed deals are read-only'; END IF;
 IF public.is_admin(auth.uid()) THEN RETURN NEW; END IF;
 IF NOT public.deal_team_access(OLD.id) THEN RAISE EXCEPTION 'Deal membership required'; END IF;
 IF NEW.stage IS DISTINCT FROM OLD.stage OR NEW.stage_history IS DISTINCT FROM OLD.stage_history THEN RAISE EXCEPTION 'Syndicate admin changes stages'; END IF;
 IF public.has_role(auth.uid(),'dcm') THEN
 FOR k IN SELECT jsonb_object_keys(coalesce(OLD.bdt_state->'f','{}')||coalesce(NEW.bdt_state->'f','{}')) LOOP IF NOT k=ANY(allowed) AND OLD.bdt_state->'f'->k IS DISTINCT FROM NEW.bdt_state->'f'->k THEN RAISE EXCEPTION 'DCM can edit structure fields only: %',k; END IF; END LOOP;
 IF (coalesce(OLD.bdt_state,'{}')-'f'-'parties') IS DISTINCT FROM (coalesce(NEW.bdt_state,'{}')-'f'-'parties') THEN RAISE EXCEPTION 'DCM can edit structure fields only'; END IF;
 SELECT coalesce(jsonb_agg(p),'[]') INTO a FROM jsonb_array_elements(coalesce(OLD.bdt_state->'parties','[]')) p WHERE NOT (p->'Roles' ? 'BOOKRUNNER');
 SELECT coalesce(jsonb_agg(p),'[]') INTO b FROM jsonb_array_elements(coalesce(NEW.bdt_state->'parties','[]')) p WHERE NOT (p->'Roles' ? 'BOOKRUNNER');
 IF a IS DISTINCT FROM b THEN RAISE EXCEPTION 'DCM can edit bookrunners, not issuer details'; END IF;
 IF NEW.deal_workspace IS DISTINCT FROM OLD.deal_workspace THEN
 SELECT coalesce(jsonb_agg(t-'id'-'label'-'currency'-'amount'-'tenor'-'rateType'-'values'),'[]') INTO a FROM jsonb_array_elements(coalesce(OLD.deal_workspace->'tranches','[]')) t;
 SELECT coalesce(jsonb_agg(t-'id'-'label'-'currency'-'amount'-'tenor'-'rateType'-'values'),'[]') INTO b FROM jsonb_array_elements(coalesce(NEW.deal_workspace->'tranches','[]')) t;
 IF a IS DISTINCT FROM b AND jsonb_array_length(coalesce(OLD.deal_workspace->'tranches','[]'))=jsonb_array_length(coalesce(NEW.deal_workspace->'tranches','[]')) THEN RAISE EXCEPTION 'DCM cannot change tranche legal status'; END IF;
 FOR k IN SELECT jsonb_object_keys(coalesce(NEW.deal_workspace->'tranches'->0->'values','{}')) LOOP IF NOT k=ANY(allowed) AND NEW.deal_workspace->'tranches'->0->'values'->k IS DISTINCT FROM OLD.deal_workspace->'tranches'->0->'values'->k THEN RAISE EXCEPTION 'DCM can edit structure fields only'; END IF; END LOOP;
 END IF;
 IF (to_jsonb(NEW)-'bdt_state'-'deal_workspace'-'updated_at'-'currency'-'size'-'tenor'-'maturity_date'-'interest_type'-'bookrunners') IS DISTINCT FROM (to_jsonb(OLD)-'bdt_state'-'deal_workspace'-'updated_at'-'currency'-'size'-'tenor'-'maturity_date'-'interest_type'-'bookrunners') THEN RAISE EXCEPTION 'DCM can edit structure fields only'; END IF;
 ELSIF public.deal_phase(OLD.id)<>'setup' THEN RAISE EXCEPTION 'Legal and counsel DTS access is read-only during execution'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER guard_deal_actor_edits BEFORE UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION public.guard_deal_actor_edits();
CREATE FUNCTION public.audit_deal_signoff() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at:=now(); INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,details) VALUES(gen_random_uuid()::text,'DEAL_SIGNOFF','deal',NEW.deal_id,coalesce(auth.uid(),NEW.user_id)::text,jsonb_build_object('item',NEW.item_key,'role',NEW.role,'status',NEW.status)::text); RETURN NEW; END $$;
CREATE TRIGGER audit_deal_signoff BEFORE INSERT OR UPDATE ON public.deal_signoffs FOR EACH ROW EXECUTE FUNCTION public.audit_deal_signoff();
CREATE FUNCTION public.reopen_deal_signoffs() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.bdt_state IS DISTINCT FROM NEW.bdt_state OR OLD.deal_workspace IS DISTINCT FROM NEW.deal_workspace THEN UPDATE public.deal_signoffs SET status='open' WHERE deal_id=NEW.id AND status<>'open'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reopen_deal_signoffs AFTER UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION public.reopen_deal_signoffs();
CREATE FUNCTION public.reopen_document_signoffs() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.deal_signoffs SET status='open' WHERE deal_id=coalesce(NEW.deal_id,OLD.deal_id) AND status<>'open'; RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER reopen_document_signoffs AFTER INSERT OR UPDATE OR DELETE ON public.deal_documents FOR EACH ROW EXECUTE FUNCTION public.reopen_document_signoffs();
ALTER PUBLICATION supabase_realtime ADD TABLE public.deal_signoffs,public.deal_team_members;